// Validate and decode the HMAC token
const crypto = require('crypto');

const config = $('Set Config').first().json.config;
const request = $input.first().json.request;

// Check if token exists
if (!request.token) {
  return {
    json: {
      valid: false,
      error: 'Missing token',
      error_code: 'TOKEN_MISSING'
    }
  };
}

// Check if action is valid
if (!['reschedule', 'cancel'].includes(request.action)) {
  return {
    json: {
      valid: false,
      error: 'Invalid action. Must be "reschedule" or "cancel"',
      error_code: 'INVALID_ACTION'
    }
  };
}

try {
  // Split token into payload and signature
  const [payloadBase64, signature] = request.token.split('.');

  if (!payloadBase64 || !signature) {
    return {
      json: {
        valid: false,
        error: 'Invalid token format',
        error_code: 'TOKEN_INVALID_FORMAT'
      }
    };
  }

  // Verify signature
  const expectedSignature = crypto
    .createHmac('sha256', config.tokenSecret)
    .update(payloadBase64)
    .digest('base64url');

  if (signature !== expectedSignature) {
    return {
      json: {
        valid: false,
        error: 'Invalid token signature',
        error_code: 'TOKEN_INVALID_SIGNATURE'
      }
    };
  }

  // Decode payload
  const payloadString = Buffer.from(payloadBase64, 'base64url').toString('utf8');
  const payload = JSON.parse(payloadString);

  // Check expiration
  const expiresAt = new Date(payload.expires_at);
  if (expiresAt < new Date()) {
    return {
      json: {
        valid: false,
        error: 'Token has expired',
        error_code: 'TOKEN_EXPIRED'
      }
    };
  }

  // Token is valid
  return {
    json: {
      valid: true,
      payload: {
        appointment_id: payload.appointment_id,
        client_email: payload.client_email,
        expires_at: payload.expires_at
      },
      request,
      config
    }
  };

} catch (error) {
  return {
    json: {
      valid: false,
      error: 'Token validation failed: ' + error.message,
      error_code: 'TOKEN_VALIDATION_ERROR'
    }
  };
}

// Merge appointment data with config and request
const appointment = $input.first().json;
const tokenData = $('Validate Token').first().json;

// Validate appointment status
if (appointment.status === 'Cancelled') {
  return {
    json: {
      valid: false,
      error: 'This appointment has already been cancelled',
      error_code: 'ALREADY_CANCELLED',
      appointment,
      config: tokenData.config,
      request: tokenData.request
    }
  };
}

// Check email matches (security)
if (appointment.client_email.toLowerCase() !== tokenData.payload.client_email.toLowerCase()) {
  return {
    json: {
      valid: false,
      error: 'Token email does not match appointment',
      error_code: 'EMAIL_MISMATCH',
      appointment,
      config: tokenData.config,
      request: tokenData.request
    }
  };
}

// Check minimum notice for changes
const appointmentStart = new Date(appointment.start_time);
const now = new Date();
const hoursUntilAppointment = (appointmentStart - now) / (1000 * 60 * 60);
const minNotice = tokenData.config.minNoticeHours || 2;

if (hoursUntilAppointment < minNotice) {
  return {
    json: {
      valid: false,
      error: `Changes must be made at least ${minNotice} hours before the appointment`,
      error_code: 'TOO_LATE_TO_CHANGE',
      appointment,
      config: tokenData.config,
      request: tokenData.request
    }
  };
}

// For reschedule, check reschedule count
if (tokenData.request.action === 'reschedule') {
  const rescheduleCount = parseInt(appointment.reschedule_count) || 0;
  const maxReschedules = tokenData.config.maxReschedules || 2;

  if (rescheduleCount >= maxReschedules) {
    return {
      json: {
        valid: false,
        error: `Maximum reschedules (${maxReschedules}) reached. Please contact us to make changes.`,
        error_code: 'MAX_RESCHEDULES_REACHED',
        appointment,
        config: tokenData.config,
        request: tokenData.request
      }
    };
  }

  // Check if new_start is provided
  if (!tokenData.request.new_start) {
    return {
      json: {
        valid: false,
        error: 'New appointment time is required for reschedule',
        error_code: 'MISSING_NEW_TIME',
        appointment,
        config: tokenData.config,
        request: tokenData.request
      }
    };
  }
}

return {
  json: {
    valid: true,
    appointment,
    config: tokenData.config,
    request: tokenData.request,
    payload: tokenData.payload
  }
};

// Validate new time slot for reschedule
const data = $input.first().json;
const config = data.config;
const appointment = data.appointment;
const newStart = new Date(data.request.new_start);

// Calculate new end time
const duration = config.appointmentDurationMinutes || 30;
const newEnd = new Date(newStart.getTime() + duration * 60 * 1000);

// Add buffers for availability check
const bufferBefore = config.bufferBeforeMinutes || 10;
const bufferAfter = config.bufferAfterMinutes || 10;
const checkStart = new Date(newStart.getTime() - bufferBefore * 60 * 1000);
const checkEnd = new Date(newEnd.getTime() + bufferAfter * 60 * 1000);

// Validate working hours and days
const dayOfWeek = newStart.getDay();
const workingDays = config.workingDays || [1, 2, 3, 4, 5];
const [startHour, startMin] = (config.workingHoursStart || '09:00').split(':').map(Number);
const [endHour, endMin] = (config.workingHoursEnd || '17:00').split(':').map(Number);

const workDayStart = new Date(newStart);
workDayStart.setHours(startHour, startMin, 0, 0);

const workDayEnd = new Date(newStart);
workDayEnd.setHours(endHour, endMin, 0, 0);

let errors = [];

// Check working day
if (!config.allowWeekends && !workingDays.includes(dayOfWeek)) {
  errors.push('Selected day is not a working day');
}

// Check working hours
if (newStart < workDayStart || newEnd > workDayEnd) {
  errors.push(`Appointment must be within working hours (${config.workingHoursStart} - ${config.workingHoursEnd})`);
}

// Check minimum notice
const now = new Date();
const minNoticeMs = (config.minNoticeHours || 2) * 60 * 60 * 1000;
if (newStart < new Date(now.getTime() + minNoticeMs)) {
  errors.push(`Appointments require at least ${config.minNoticeHours} hours notice`);
}

// Check max days ahead
const maxAheadMs = (config.maxDaysAhead || 60) * 24 * 60 * 60 * 1000;
if (newStart > new Date(now.getTime() + maxAheadMs)) {
  errors.push(`Appointments cannot be booked more than ${config.maxDaysAhead} days in advance`);
}

return {
  json: {
    ...data,
    newTime: {
      start: newStart.toISOString(),
      end: newEnd.toISOString(),
      checkStart: checkStart.toISOString(),
      checkEnd: checkEnd.toISOString()
    },
    validation: {
      valid: errors.length === 0,
      errors
    }
  }
};

// Filter out the current appointment from conflicts
const events = $input.all().map(item => item.json);
const data = $('Validate New Time').first().json;
const currentEventId = data.appointment.calendar_event_id;

// Filter out current event (since we're updating it)
const conflicts = events.filter(event => event.id !== currentEventId);

return {
  json: {
    ...data,
    hasConflict: conflicts.length > 0,
    conflicts
  }
};
